using namespace std;

const int SZ = 400;


template<size_t SZ> int compute_inv(const vector<bitset<SZ>>& mat, vector<bitset<SZ>>& inv) {
    int n = mat.size();
    vector<bool> empty(n, true);
    vector<bitset<SZ>> basis(n);

    for(int i = 0; i < n; i++) {
        bitset<SZ> cur = mat[i];
        bitset<SZ> curinv;
        curinv[i] = 1;
        for(int j = 0; j < n; j++) {
            if(cur[j]) {
                if(empty[j]) {
                    basis[j] = cur;
                    inv[j] = curinv;
                    empty[j] = false;
                    break;
                } else {
                    cur ^= basis[j];
                    curinv ^= inv[j];
                }
            }
        }
    }
    for(int i = 0; i < n; i++) {
        if(empty[i]) return 0;
    }

    for(int i = n - 1; i >= 1; i--) {
        for(int j = 0; j < i; j++) {
            if(basis[j][i]) {
                basis[j] ^= basis[i];
                inv[j] ^= inv[i];
            }
        }
    }
    return 1;
}

void tc() {
    int n, m; cin >> n >> m;
    vector<bitset<SZ>> mat(n);
    for(int i = 0; i < m; i++) {
        int x, y; cin >> x >> y;
        x--, y--;
        mat[x][y] = 1;
    }

    vector<bitset<SZ>> inv(n);
    compute_inv(mat, inv);
    vector<int> cnts(2 * n);
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            cnts[i] += mat[i][j];
            cnts[n + j] += mat[i][j];
        }
    }
    queue<pair<int, int>> mustq, freeq;
    vector<pair<int, int>> centers;
    vector<vector<pair<int, int>>> moves;
    while(true) {
        while(mustq.size() + freeq.size() < n) {
            int best_rc = 0;
            for(int rc = 0; rc < 2 * n; rc++) {
                if(cnts[rc] >= cnts[best_rc]) best_rc = rc;
            }
            if(cnts[best_rc] == 0) {
                break;
            }

            int x = -1, y = -1;
            if(best_rc < n) {
                x = best_rc;
                for(int j = 0; j < n; j++) {
                    if(mat[x][j] && inv[j][x]) {
                        y = j;
                        break;
                    }
                }
            } else {
                y = best_rc - n;
                for(int j = 0; j < n; j++) {
                    if(mat[j][y] && inv[y][j]) {
                        x = j;
                        break;
                    }
                }
            }
            assert(x != -1 && y != -1);

            centers.push_back({x, y});
            vector<pair<int, int>> must, free;
            auto erase = [&] (int a, int b) {
                mat[a][b] = 0;
                cnts[a]--;
                cnts[b + n]--;
            };
            for(int j = 0; j < n; j++) {
                if(mat[x][j] && j != y) {
                    must.push_back({x, j});
                    erase(x, j);
                }
            }
            for(int j = 0; j < n; j++) {
                if(mat[j][y] && j != x) {
                    free.push_back({j, y});
                    erase(j, y);
                }
            }
            erase(x, y);
            assert(cnts[x] == 0 && cnts[n + y] == 0);

            if(best_rc < n) swap(must, free);
            for(auto u : must) mustq.push(u);
            for(auto u : free) freeq.push(u);

            bitset<SZ> row = inv[y];
            for(int j = 0; j < n; j++) {
                if(cnts[j + n] > 0 && inv[j][x]) {
                    inv[j] ^= row;
                }
            }
        }
        int left = n;
        vector<pair<int, int>> move;
        while(left > 0 && mustq.size() > 0) {
            left--;
            move.push_back(mustq.front());
            mustq.pop();
        }
        while(left > 0 && freeq.size() > 0) {
            left--;
            move.push_back(freeq.front());
            freeq.pop();
        }
        while(left > 0 && centers.size() > 0) {
            left--;
            move.push_back(centers.back());
            centers.pop_back();
        }
        moves.push_back(move);
        if(centers.size() == 0) break;
    }
    cout << moves.size() << "\n";
    for(auto move : moves) {
        cout << move.size() << "\n";
        for(auto [u, v] : move) cout << u + 1 << " " << v + 1 << "\n";
    }
}

int main() {
    ios::sync_with_stdio(false), cin.tie(nullptr);
    int t; cin >> t;
    while(t--) tc();
}
